class RunningTotal:
    """Accumulates numbers one at a time, starting from zero."""

    def __init__(self, start=0):
        self.value = start

    def add(self, amount):
        self.value += amount
        return self.value


class NumericToken:
    """A single piece of raw text that should describe a number."""

    def __init__(self, raw):
        self.raw = raw.strip()

    def to_number(self):
        if not self.raw:
            raise ValueError("empty numeric token")
        try:
            return int(self.raw)
        except ValueError:
            return float(self.raw)


class DataColumn:
    """A labelled series of numbers."""

    def __init__(self, label, numbers):
        self.label = label
        self.numbers = numbers

    def total(self):
        return sum_list(self.numbers)

    def mean(self):
        if not self.numbers:
            return 0.0
        return self.total() / len(self.numbers)


class DatasetParser:
    """Turns ``label: n, n, n`` lines into columns of numbers."""

    def __init__(self, separator=":", delimiter=","):
        self.separator = separator
        self.delimiter = delimiter

    def parse_numbers(self, text):
        parts = text.split(self.delimiter)
        return [NumericToken(part).to_number() for part in parts if part.strip()]

    def parse_column(self, line):
        label, found, rest = line.partition(self.separator)
        if not found:
            raise ValueError("missing %r in column definition: %r" % (self.separator, line))
        return DataColumn(label.strip(), self.parse_numbers(rest))

    def parse(self, lines):
        return [self.parse_column(line) for line in lines]


class ColumnReport:
    """Renders a set of columns as aligned text rows."""

    def __init__(self, columns):
        self.columns = columns
        self.width = max((len(c.label) for c in columns), default=6)

    def lines(self):
        rows = ["{:<{w}}  {:>5}  {:>10}  {:>10}".format(
            "column", "n", "total", "mean", w=self.width)]
        for column in self.columns:
            rows.append("{:<{w}}  {:>5}  {:>10}  {:>10.2f}".format(
                column.label, len(column.numbers), column.total(),
                column.mean(), w=self.width))
        return rows


def sum_list(numbers):
    total = RunningTotal()
    for number in numbers:
        total.add(number)
    return total.value


def main():
    dataset = [
        "morning sales: 1, 2, 3, 4",
        "evening sales: 10, 20.5, 30",
        "night sales:",
    ]
    columns = DatasetParser().parse(dataset)
    for line in ColumnReport(columns).lines():
        print(line)
    print("grand total:", sum_list([column.total() for column in columns]))


if __name__ == "__main__":
    main()

