class NumberContainer:
    def __init__(self, value):
        self.containedValue = value

class MaxFinder:
    def findLargest(self, inputList):
        currentMax = NumberContainer(inputList[0])
        for number in inputList[1:]:
            possibleNewMax = NumberContainer(number)
            if possibleNewMax.containedValue > currentMax.containedValue:
                currentMax = possibleNewMax
        return currentMax.containedValue

class InputDataProcessor:
    def __init__(self, data):
        self.inputData = data

class ResultHolder:
    def __init__(self, result):
        self.finalResult = result

class MainApplication:
    def run(self, numberList):
        processor = InputDataProcessor(numberList)
        finder = MaxFinder()
        max_value = finder.findLargest(processor.inputData)
        holder = ResultHolder(max_value)
        return holder.finalResult

def find_max(numbers):
    app = MainApplication()
    return app.run(numbers)

