    inputMeasure = ScoreInput(scoreValue)
    ruleConfiguration = GradeRuleSet()
    gradeProcesser = ScoreEvaluator(sorted(ruleConfiguration.Rules, key=lambda x: x.HighLimit, reverse=True))
    outputGrade = gradeProcesser.determineGrade(inputMeasure.RawValue)
    return GradeResult(outputGrade).FinalLetter

