class TextNormalizer:
    """Decides which characters take part in the uniqueness test."""

    def __init__(self, case_sensitive=True, ignore_whitespace=False):
        self.case_sensitive = case_sensitive
        self.ignore_whitespace = ignore_whitespace

    def apply(self, text):
        chars = text if self.case_sensitive else text.lower()
        if self.ignore_whitespace:
            chars = "".join(c for c in chars if not c.isspace())
        return chars

    def describe(self):
        mode = "case-sensitive" if self.case_sensitive else "case-folded"
        space = "spaces ignored" if self.ignore_whitespace else "spaces counted"
        return "%s, %s" % (mode, space)


class DuplicateGroup:
    """A repeated character together with the positions where it occurs."""

    def __init__(self, char, positions):
        self.char = char
        self.positions = positions

    def label(self):
        spots = ", ".join(str(p) for p in self.positions)
        return "%r x%d at %s" % (self.char, len(self.positions), spots)


class CharacterTally:
    """Positions of every character of an already normalized string."""

    def __init__(self, chars):
        self.positions = {}
        for index, char in enumerate(chars):
            self.positions.setdefault(char, []).append(index)

    def is_unique(self):
        return all(len(spots) == 1 for spots in self.positions.values())

    def duplicate_groups(self):
        return [DuplicateGroup(c, p) for c, p in self.positions.items() if len(p) > 1]


class UniquenessResult:
    """Outcome of testing one string."""

    def __init__(self, text, unique, groups):
        self.text = text
        self.unique = unique
        self.groups = groups

    def summary(self):
        if self.unique:
            return "%r: unique" % self.text
        detail = "; ".join(group.label() for group in self.groups)
        return "%r: repeats %s" % (self.text, detail)


class ScanReport:
    """Formats the results of scanning a batch of strings."""

    def __init__(self, normalizer, results):
        self.normalizer = normalizer
        self.results = results

    def render(self):
        lines = ["Filter: %s" % self.normalizer.describe()]
        for result in self.results:
            lines.append("  " + result.summary())
        return "\n".join(lines)


def has_unique_chars(s):
    normalizer = TextNormalizer()
    tally = CharacterTally(normalizer.apply(s))
    return tally.is_unique()


def analyze(text, normalizer):
    tally = CharacterTally(normalizer.apply(text))
    return UniquenessResult(text, tally.is_unique(), tally.duplicate_groups())


def main():
    samples = ["abc", "abca", "Aa", "the quick", ""]
    strict = TextNormalizer()
    relaxed = TextNormalizer(case_sensitive=False, ignore_whitespace=True)
    for normalizer in (strict, relaxed):
        report = ScanReport(normalizer, [analyze(t, normalizer) for t in samples])
        print(report.render())


if __name__ == "__main__":
    main()

