        self.value = value

class SecondListElement:
    def __init__(self, value):
        self.value = value

class DifferenceFinder:
    def find_difference(self, list_one, list_two):
        set_one = {item.value for item in list_one}
        set_two = {item.value for item in list_two}
        return list(set_one - set_two)

class ResultContainer:
    def __init__(self, result_list):
        self.result_list = result_list

class ListProcessor:
    def process(self, list1, list2):
        wrapped_list_one = [FirstListElement(item) for item in list1]
        wrapped_list_two = [SecondListElement(item) for item in list2]
        finder = DifferenceFinder()
        diff_values = finder.find_difference(wrapped_list_one, wrapped_list_two)
