class TableGenerator:
    def __init__(self):
        pass

    def generate_entries(self, base_num_obj, limit_factor):
        table_entries = []
        for i in range(1, limit_factor.value + 1):
            current_factor = MultiplicationFactor(i)
            product = ProductResult(base_num_obj.value * current_factor.value)
            formatted_str = f"{base_num_obj.value} x {current_factor.value} = {product.value}"
            table_entries.append(FormattedEntry(formatted_str))
        return [entry.entry_string for entry in table_entries]

