def calculate_range(numbers):
    number_collection = NumberList(numbers)
    if not number_collection.values:
        return 0

    extremum_service = ExtremumFinder()
    min_value = extremum_service.find_minimum(number_collection.values)
    max_value = extremum_service.find_maximum(number_collection.values)

    calculator_service = RangeCalculator()
    data_range = calculator_service.calculate_difference(max_value, min_value)

    output_object = ResultContainer(data_range)
    display_service = DisplayOutput()
    return display_service.get_result(output_object)

