class HexDigitValue:
    def __init__(self, char):
        self.char = char

    def get_decimal(self):
        return int(self.char, 16)

class PowerOfSixteen:
    def __init__(self, power_index):
        self.power_index = power_index

    def get_value(self):
        return 16 ** self.power_index

class DigitPosition:
    def __init__(self, original_index, total_length):
        self.original_index = original_index
        self.total_length = total_length

    def get_power_index(self):
        return self.total_length - 1 - self.original_index

class CalculatedTerm:
    def __init__(self, digit_value, power_value):
        self.digit_value = digit_value
        self.power_value = power_value

    def get_term(self):
        return self.digit_value * self.power_value

class DecimalAccumulator:
    def __init__(self):
        self.total_sum = 0

    def add_term(self, term):
        self.total_sum += term

    def get_total(self):
        return self.total_sum

def hex_to_decimal(hex_string):
    accumulator = DecimalAccumulator()
    string_length = len(hex_string)
    for i, char in enumerate(hex_string):
        digit_value_obj = HexDigitValue(char)
        decimal_digit = digit_value_obj.get_decimal()

        position_obj = DigitPosition(i, string_length)
        power_index = position_obj.get_power_index()

        power_obj = PowerOfSixteen(power_index)
        sixteen_power = power_obj.get_value()

        term_obj = CalculatedTerm(decimal_digit, sixteen_power)
        accumulator.add_term(term_obj.get_term())
    return accumulator.get_total()

