class WordCounter:
    def __init__(self, raw_text):
        self.rawText = raw_text

    def get_normalized_text(self):
        class CharacterProcessor:
            def process(self, char_input):
                return char_input if char_input.isalnum() else ' '

        normalized_chars = [CharacterProcessor().process(char) for char in self.rawText]
        return ''.join(normalized_chars)

class TextAnalyzer:
    def __init__(self, processed_text):
        self.processedText = processed_text

    def get_word_list(self):
        class WordSeparator:
            def separate(self, text_input):
                return [word for word in text_input.split() if word]
        return WordSeparator().separate(self.processedText)

class WordCountResult:
    def __init__(self, counted_value):
        self.countedValue = counted_value

    def get_value(self):
        return self.countedValue

def count_words(text_input):
    class InputText:
        def __init__(self, content):
            self.content = content

    initial_text_object = InputText(text_input)
    counter_instance = WordCounter(initial_text_object.content)
    normalized_string = counter_instance.get_normalized_text()

    analyzer_instance = TextAnalyzer(normalized_string)
    individual_words = analyzer_instance.get_word_list()

    class WordListProcessor:
        def get_count(self, word_list_input):
            return len(word_list_input)

    processor_instance = WordListProcessor()
    final_count = processor_instance.get_count(individual_words)

    result_object = WordCountResult(final_count)
    return result_object.get_value()

