class StringGroup:
    def __init__(self, strings):
        if not isinstance(strings, list) or not all(isinstance(s, str) for s in strings):
            raise TypeError("strings must be a list of str")
        self.items = list(strings)

    def shortest(self):
        return min(self.items, key=len)


class CharacterColumn:
    def __init__(self, group, index):
        self.letters = [item[index] for item in group.items]

    def is_uniform(self):
        return len(set(self.letters)) == 1


class PrefixMatch:
    def __init__(self, prefix, divergence_index, group_size):
        self.prefix = prefix
        self.divergence_index = divergence_index
        self.group_size = group_size

    def describe(self):
        if not self.prefix:
            return "no common prefix among %d string(s)" % self.group_size
        return "common prefix %r shared by %d string(s)" % (self.prefix, self.group_size)


class PrefixScanner:
    def __init__(self, group):
        self.group = group

    def scan(self):
        if not self.group.items:
            return PrefixMatch("", 0, 0)
        base = self.group.shortest()
        index = 0
        while index < len(base):
            column = CharacterColumn(self.group, index)
            if not column.is_uniform():
                break
            index += 1
        return PrefixMatch(base[:index], index, len(self.group.items))


class DivergenceReport:
    def __init__(self, group, match):
        self.group = group
        self.match = match

    def lines(self):
        cut = self.match.divergence_index
        rendered = [self.match.describe()]
        for item in self.group.items:
            rendered.append("  %s|%s" % (item[:cut], item[cut:]))
        return rendered


def report_lines(strings):
    group = StringGroup(strings)
    match = PrefixScanner(group).scan()
    return DivergenceReport(group, match).lines()


def longest_common_prefix(strings):
    group = StringGroup(strings)
    return PrefixScanner(group).scan().prefix


def main():
    for dataset in (["flower", "flow", "flight"], ["dog", "racecar", "car"],
                    ["interspecies", "interstellar", "interstate"]):
        print("\n".join(report_lines(dataset)))
        print("longest_common_prefix(%r) -> %r" % (dataset, longest_common_prefix(dataset)))


if __name__ == "__main__":
    main()

