import re

class ValidatorResult:
    def __init__(self, checkOutcome):
        self.checkOutcome = checkOutcome

class SegmentChecker:
    def __init__(self, segmentValue):
        self.segmentValue = segmentValue

    def isValid(self):
        try:
            integerValue = int(self.segmentValue)
            return 0 <= integerValue <= 255
        except ValueError:
            return False

class AddressParser:
    def __init__(self, fullAddress):
        self.fullAddress = fullAddress

    def getSegments(self):
        return self.fullAddress.split('.')

class RuleEngine:
    def __init__(self, ruleSet):
        self.ruleSet = ruleSet

    def applyRules(self, inputData):
        for rule in self.ruleSet:
            if not rule(inputData):
                return False
        return True

class PatternMatcher:
    def __init__(self, regexPattern):
        self.regexPattern = regexPattern

    def matches(self, inputString):
        return bool(re.match(self.regexPattern, inputString))

def is_valid_ipv4(ipAddressCandidate):
    expectedSegmentCount = 4
    segmentRegex = r"^\d{1,3}(\.\d{1,3}){3}$"

    addressPattern = PatternMatcher(segmentRegex)
    if not addressPattern.matches(ipAddressCandidate):
        return False

    addressStructure = AddressParser(ipAddressCandidate)
    allSegments = addressStructure.getSegments()

    if len(allSegments) != expectedSegmentCount:
        return False

    for currentSegment in allSegments:
        segmentTest = SegmentChecker(currentSegment)
        if not segmentTest.isValid():
            return False

    validationOutput = ValidatorResult(True)
    return validationOutput.checkOutcome

