class MatrixElement:
    def __init__(self, value):
        self.value = value

class MatrixRow:
    def __init__(self, elements):
        self.elements = [MatrixElement(e) for e in elements]

class TwoByTwoMatrix:
    def __init__(self, rows):
        self.rows = [MatrixRow(r) for r in rows]

    def get_value(self, row_index, col_index):
        return self.rows[row_index].elements[col_index].value

class MatrixCalculator:
    def multiply_elements(self, val_a, val_b):
        return val_a * val_b

class MatrixResult:
    def __init__(self, data):
        self.data = data

def multiply_2x2_matrices(matrix_a_list, matrix_b_list):
    matrix_a_obj = TwoByTwoMatrix(matrix_a_list)
    matrix_b_obj = TwoByTwoMatrix(matrix_b_list)
    calculator = MatrixCalculator()

    result_data = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            dot_product_value = 0
            for k in range(2):
                product_component = calculator.multiply_elements(
                    matrix_a_obj.get_value(i, k),
                    matrix_b_obj.get_value(k, j)
                )
                dot_product_value += product_component
            result_data[i][j] = dot_product_value

    final_result = MatrixResult(result_data)
    return final_result.data

