import re

class WordCounter:
    def __init__(self, textContent):
        self.textContent = textContent

    def countWords(self):
        words = re.findall(r'\b\w+\b', self.textContent.lower())
        return len(words)

class FilePath:
    def __init__(self, pathString):
        self.pathString = pathString

class FileReader:
    def readContents(self, filePathObject):
        with open(filePathObject.pathString, 'r') as fileHandle:
            return fileHandle.read()

class TextProcessor:
    def __init__(self, rawText):
        self.rawText = rawText

    def getCleanText(self):
        return self.rawText.strip()

class WordCountResult:
    def __init__(self, countValue):
        self.countValue = countValue

def count_words_in_file(filepath):
    fileLocator = FilePath(filepath)
    readerInstance = FileReader()
    fileContent = readerInstance.readContents(fileLocator)
    processorInstance = TextProcessor(fileContent)
    cleanedText = processorInstance.getCleanText()
    counterInstance = WordCounter(cleanedText)
    wordNumber = counterInstance.countWords()
    finalResult = WordCountResult(wordNumber)
    return finalResult.countValue

