from collections import OrderedDict

class DictionarySorter:
    def __init__(self, original_dict):
        self.originalDictionary = original_dict

    def get_sorted_dictionary(self):
        return OrderedDict(sorted(self.originalDictionary.items()))

class InputDataProcessor:
    def __init__(self, data_input):
        self.inputPayload = data_input

    def process_input(self):
        return self.inputPayload

class OutputDataCollector:
    def __init__(self):
        self.collectedResults = {}

    def add_result(self, key_name, value_content):
        self.collectedResults[key_name] = value_content

class KeyValueItem:
    def __init__(self, key_value, item_value):
        self.itemKey = key_value
        self.itemContent = item_value

class ResultContainer:
    def __init__(self, final_output):
        self.finalResult = final_output

def sort_dict_by_key(input_dict):
    initial_processor = InputDataProcessor(input_dict)
    processed_input = initial_processor.process_input()

    sorter_instance = DictionarySorter(processed_input)
    sorted_ordered_dict = sorter_instance.get_sorted_dictionary()

    output_collector = OutputDataCollector()
    for key, value in sorted_ordered_dict.items():
        item_unit = KeyValueItem(key, value)
        output_collector.add_result(item_unit.itemKey, item_unit.itemContent)

    final_container = ResultContainer(output_collector.collectedResults)
    return final_container.finalResult

