class ExponentValidator:
    def __init__(self, base, exponent):
        self.base = base
        self.exponent = exponent

    def validated(self):
        if isinstance(self.exponent, bool) or not isinstance(self.exponent, int):
            raise TypeError("exponent must be an int")
        if isinstance(self.base, bool) or not isinstance(self.base, (int, float)):
            raise TypeError("base must be an int or a float")
        if self.base == 0 and self.exponent < 0:
            raise ZeroDivisionError("0 cannot be raised to a negative exponent")
        return self.base, self.exponent


class PowerExpression:
    def __init__(self, base, exponent):
        self.base, self.exponent = ExponentValidator(base, exponent).validated()

    def evaluate(self):
        result = 1
        factor = self.base
        remaining = abs(self.exponent)
        while remaining:
            if remaining & 1:
                result *= factor
            factor *= factor
            remaining >>= 1
        if self.exponent < 0:
            return 1 / result
        return result

    def __str__(self):
        return "{}^{}".format(self.base, self.exponent)


def calculate_power(base, exponent):
    return PowerExpression(base, exponent).evaluate()


class PowerResult:
    def __init__(self, value):
        self.value = value

    def text(self):
        if isinstance(self.value, float):
            return "{:.6g}".format(self.value)
        return str(self.value)


