        except (TypeError, ZeroDivisionError) as error:
            table.add(ReportRow("{}^{}".format(base, exponent), str(error)))
            continue
        result = PowerResult(expression.evaluate())
        row = ReportRow(str(expression), result.text())
        table.add(row)
    print(table.render())


if __name__ == "__main__":
