class RangeBoundary:
    def __init__(self, value):
        self.value = value

class RangeInstance:
    def __init__(self, start_value, end_value):
        self.startPoint = RangeBoundary(start_value)
        self.endPoint = RangeBoundary(end_value)

class OverlapCalculator:
    def calculate(self, range1, range2):
        start1, end1 = range1
        start2, end2 = range2

        max_start = max(start1, start2)
        min_end = min(end1, end2)

        if max_start < min_end:
            return OverlapResult(max_start, min_end)
        else:
            return NoOverlapIndicator()

class OverlapResult:
    def __init__(self, start, end):
        self.overlapStart = RangeBoundary(start)
        self.overlapEnd = RangeBoundary(end)
        self.hasOverlap = True

    def to_tuple(self):
        return (self.overlapStart.value, self.overlapEnd.value)

class NoOverlapIndicator:
    def __init__(self):
        self.hasOverlap = False

class ResultConverter:
    def convert(self, overlap_object):
        if overlap_object.hasOverlap:
            return overlap_object.to_tuple()
        else:
            return None

class FunctionWrapper:
    def __init__(self, calculator, converter):
        self.overlapCalculator = calculator
        self.resultConverter = converter

    def find_overlap(self, range1, range2):
        range_object1 = RangeInstance(range1[0], range1[1])
        range_object2 = RangeInstance(range2[0], range2[1])
        calculation_outcome = self.overlapCalculator.calculate(
            (range_object1.startPoint.value, range_object1.endPoint.value),
            (range_object2.startPoint.value, range_object2.endPoint.value)
        )
        return self.resultConverter.convert(calculation_outcome)

def range_overlap(range1, range2):
    overlap_calc = OverlapCalculator()
    result_conv = ResultConverter()
    function_inst = FunctionWrapper(overlap_calc, result_conv)
    return function_inst.find_overlap(range1, range2)

