class IsbnDigitProcessor:
    def process_char(self, char_code):
        if '0' <= char_code <= '9':
            return int(char_code)
        elif char_code == 'X' or char_code == 'x':
            return 10
        return -1

class ChecksumCalculator:
    def calculate_remainder(self, total_sum):
        return total_sum % 11

class IsbnValidator:
    def is_valid_length(self, input_string):
        return len(input_string) == 10

