    def __init__(self):
        pass

    def join_lines(self, lines_list):
        return "\n".join(lines_list)

class InputValidator:
    def __init__(self):
        pass

    def validate_input(self, words_list, width_val):
        if not isinstance(words_list, list) or not all(isinstance(w, str) for w in words_list):
            raise TypeError("Words must be a list of strings.")
        if not isinstance(width_val, int) or width_val <= 0:
            raise ValueError("Max width must be a positive integer.")

def justify_text_simple(words, max_width):
    input_checker = InputValidator()
    input_checker.validate_input(words, max_width)

    formatting_process = JustificationEngine(max_width)
    result_lines = formatting_process.process_words(words)

    final_output_producer = TextFormatter()
    return final_output_producer.join_lines(result_lines)

