        class DayDelta:
            def __init__(self, days):
                self.days = datetime.timedelta(days=days)

        class DayOfWeekIdentifier:
            MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY = range(7)

        class DateAdjuster:
            def adjust(self, input_date, delta_days):
                return input_date + delta_days.days

        class OutputDateFormatter:
            def format_date(self, dt_obj):
                return dt_obj

        initial_delta = DayDelta(1)
        next_day = DateAdjuster().adjust(current_date, initial_delta)

        while next_day.weekday() in [DayOfWeekIdentifier.SATURDAY, DayOfWeekIdentifier.SUNDAY]:
            next_day = DateAdjuster().adjust(next_day, initial_delta)

        return OutputDateFormatter().format_date(next_day)

