class EmployeeRecord:
    def __init__(self, identifier, personName, deptName):
        self.employeeIdentifier = identifier
        self.personName = personName
        self.departmentName = deptName

    def toDictionary(self):
        return {'id': self.employeeIdentifier, 'name': self.personName, 'department': self.departmentName}

class DatabaseManager:
    def __init__(self, initialRecords):
        self.storageFacility = initialRecords

    def retrieveRecordById(self, recordIdentifier):
        for dataEntry in self.storageFacility:
            if dataEntry['id'] == recordIdentifier:
                return dataEntry
        return None

    def insertNewRecord(self, newRecord):
        self.storageFacility.append(newRecord.toDictionary())
        return True

class OperationResult:
    def __init__(self, successStatus):
        self.wasSuccessful = successStatus

class IdentifierChecker:
    def __init__(self, existingIdentifiers):
        self.idSet = set(existingIdentifiers)

    def isIdentifierPresent(self, identifierValue):
        return identifierValue in self.idSet

class DatabaseModifier:
    def __init__(self, dataCollection):
        self.dataCollection = dataCollection

    def addEmployee(self, dataStorage, employeeIdentifier, employeeName, employeeDepartment):
        currentIdentifiers = [entry['id'] for entry in dataStorage]
        idCheck = IdentifierChecker(currentIdentifiers)
        if idCheck.isIdentifierPresent(employeeIdentifier):
            return OperationResult(False).wasSuccessful

        personRecord = EmployeeRecord(employeeIdentifier, employeeName, employeeDepartment)
        dataStorage.append(personRecord.toDictionary())
        return OperationResult(True).wasSuccessful

def add_employee(db, employee_id, name, department):
    modifier = DatabaseModifier(db)
    return modifier.addEmployee(db, employee_id, name, department)

