    def __init__(self, rulesCollection):
        self.rules = rulesCollection

def is_valid_passport_number(candidateNumber):
    inputSequence = DigitSequence(candidateNumber)
    lengthRule = LengthRequirement(9)
    charValidation = CharacterValidator(inputSequence.sequenceData)

    allRules = RuleSet([lengthRule, charValidation]) 

    lengthMatches = ValidationResult(len(inputSequence.sequenceData) == lengthRule.requiredLength)
    if not lengthMatches.outcome:
        return False

    allDigits = ValidationResult(inputSequence.sequenceData.isdigit())
    if not allDigits.outcome:
        return False

    return True

