        self.value = value

class IntervalBoundary:
    def __init__(self, point):
        self.point = point

class StartMarker(IntervalBoundary):
    pass

class EndMarker(IntervalBoundary):
    pass

class TimeInterval:
    def __init__(self, start_time_value, end_time_value):
        self.start = StartMarker(TimePoint(start_time_value))
        self.end = EndMarker(TimePoint(end_time_value))

class OverlapChecker:
    def __init__(self):
        pass

    def determine_overlap(self, interval_one, interval_two):
        condition_one = interval_one.start.point.value <= interval_two.end.point.value
        condition_two = interval_two.start.point.value <= interval_one.end.point.value
        return condition_one and condition_two

class OverlapResult:
    def __init__(self, is_overlapping):
        self.is_overlapping = is_overlapping

class SolutionProcessor:
    def __init__(self):
        self.checker = OverlapChecker()

    def process_intervals(self, raw_interval_one, raw_interval_two):
        interval_object_one = TimeInterval(raw_interval_one[0], raw_interval_one[1])
        interval_object_two = TimeInterval(raw_interval_two[0], raw_interval_two[1])
        overlap_status = self.checker.determine_overlap(interval_object_one, interval_object_two)
        final_result = OverlapResult(overlap_status)
        return final_result.is_overlapping

def check_interval_overlap(interval1, interval2):
