import re


class TokenNormalizer:
    """Lowercases text and splits it into bare words, dropping punctuation."""
    pattern = re.compile(r"[a-z0-9']+")

    def words(self, text):
        for match in self.pattern.finditer(text.lower()):
            stripped = match.group().strip("'")
            if stripped:
                yield stripped


class WordToken:
    def __init__(self, text, index):
        self.text = text
        self.index = index


class ShortestSelector:
    def __init__(self, tokens):
        self.tokens = tokens

    def best(self):
        return min(self.tokens, key=lambda token: len(token.text), default=None)


class ReportFormatter:
    def __init__(self, sentence, token):
        self.sentence = sentence
        self.token = token

    def render(self):
        if self.token is None:
            return "{!r} -> (no words)".format(self.sentence)
        return "{!r} -> {!r} (word #{})".format(
            self.sentence, self.token.text, self.token.index + 1)


class SentenceScanner:
    """Normalizes one sentence and finds its shortest word."""

    def __init__(self, sentence):
        self.sentence = sentence or ""
        self.normalizer = TokenNormalizer()

    def tokens(self):
        words = self.normalizer.words(self.sentence)
        return [WordToken(word, index) for index, word in enumerate(words)]

    def shortest(self):
        return ShortestSelector(self.tokens()).best()

    def report(self):
        return ReportFormatter(self.sentence, self.shortest()).render()


class ScanSession:
    def __init__(self, sentences):
        self.sentences = sentences

    def lines(self):
        for sentence in self.sentences:
            yield SentenceScanner(sentence).report()


def find_shortest_word(sentence):
    token = SentenceScanner(sentence).shortest()
    return token.text if token is not None else ""


def main():
    session = ScanSession(["Hello world, this is a test.", "Programming is fun."])
    for line in session.lines():
        print(line)


if __name__ == "__main__":
    main()

