    def __init__(self, value):
        self.TermValue = value

class CalculationResult:
    def __init__(self, finalSum):
        self.OverallSum = finalSum

class RatioHandler:
    def __init__(self, commonRatio):
        self.RatioFactor = commonRatio

class TermCounter:
    def __init__(self, count):
        self.TotalCount = count

class InitialValue:
    def __init__(self, startingValue):
        self.FirstValue = startingValue

def geometric_series_sum(initialTerm, commonRatio, numberOfTerms):
    first = InitialValue(initialTerm)
    ratio = RatioHandler(commonRatio)
    count = TermCounter(numberOfTerms)

    if ratio.RatioFactor == 1:
        sumValue = first.FirstValue * count.TotalCount
    else:
        numerator = first.FirstValue * (1 - ratio.RatioFactor ** count.TotalCount)
        denominator = 1 - ratio.RatioFactor
        sumValue = numerator / denominator

    result = CalculationResult(sumValue)
    return result.OverallSum

