class SpatialPoint:
    def __init__(self, coordX, coordY):
        self.xValue = coordX
        self.yValue = coordY

class CircularRegion:
    def __init__(self, centralPoint, spanDistance):
        self.centerPoint = centralPoint
        self.radiusSize = spanDistance

class DistanceMeasurement:
    @staticmethod
    def calculateEuclidean(pointOne, pointTwo):
        return ((pointOne.xValue - pointTwo.xValue)**2 + (pointOne.yValue - pointTwo.yValue)**2)**0.5

class ProximityEvaluator:
    @staticmethod
    def checkContainment(targetPoint, referenceCircle):
        distFromCenter = DistanceMeasurement.calculateEuclidean(targetPoint, referenceCircle.centerPoint)
        return distFromCenter <= referenceCircle.radiusSize

class SolutionOutcome:
    def __init__(self, finalResult):
        self.decisionResult = finalResult

def is_point_in_circle(px, py, cx, cy, radius):
    pointOfInterest = SpatialPoint(px, py)
    circleCenterLocation = SpatialPoint(cx, cy)
    boundaryShape = CircularRegion(circleCenterLocation, radius)
    inclusionCheck = ProximityEvaluator.checkContainment(pointOfInterest, boundaryShape)
    finalAnswer = SolutionOutcome(inclusionCheck)
    return finalAnswer.decisionResult

