from datetime import date
import sys

DEFAULT_TODAY = date(2023, 10, 26)


class InvalidBirthdateError(ValueError):
    """Raised when a birthdate cannot be used for an age calculation."""


class PersonRecord:
    def __init__(self, name, birthdate):
        self.name = name
        self.birthdate = birthdate


def parse_entry(text):
    name, sep, iso = text.partition("=")
    if not sep:
        raise InvalidBirthdateError("expected NAME=YYYY-MM-DD, got %r" % text)
    return PersonRecord(
        name.strip(), date.fromisoformat(iso.strip())
    )


class ReferenceClock:
    def __init__(self, today):
        self.today = today


class BirthdateValidator:
    def check(self, birthdate, today):
        if not isinstance(birthdate, date):
            raise InvalidBirthdateError("birthdate must be a datetime.date")
        if birthdate > today:
            raise InvalidBirthdateError("birthdate %s is in the future" % birthdate)


class AgeCalculator:
    def __init__(self, clock, validator):
        self.clock = clock
        self.validator = validator

    def years(self, birthdate):
        today = self.clock.today
        self.validator.check(birthdate, today)
        age = today.year - birthdate.year
        if (today.month, today.day) < (birthdate.month, birthdate.day):
            age -= 1
        return age


def make_calculator(today=DEFAULT_TODAY):
    return AgeCalculator(
        ReferenceClock(today),
        BirthdateValidator(),
    )


def calculate_age(birthdate):
    return make_calculator().years(birthdate)


class AgeReportRow:
    def __init__(self, name, age):
        self.name, self.age = name, age

    def render(self):
        return "%-12s %3d" % (self.name, self.age)


class AgeReport:
    def __init__(self, calculator):
        self.calculator = calculator

    def render(self, records):
        rows = [
            AgeReportRow(r.name, self.calculator.years(r.birthdate))
            for r in records
        ]
        return "\n".join(row.render() for row in rows)


def main(argv):
    records = [parse_entry(arg) for arg in argv[1:]]
    print(
        AgeReport(make_calculator()).render(records)
    )


if __name__ == "__main__":
    main(sys.argv)

