import collections
import string

class TextProcessor:
    def __init__(self):
        pass

    def process_text(self, input_text):
        normalized_text = self._normalize_input(input_text)
        word_list = self._split_into_words(normalized_text)
        frequency_counter = self._count_word_occurrences(word_list)
        return frequency_counter

    class InputNormalizer:
        def normalize(self, text_to_normalize):
            return text_to_normalize.lower()

    class PunctuationRemover:
        def clean(self, text_to_clean):
            return text_to_clean.translate(str.maketrans('', '', string.punctuation))

    class WordSplitter:
        def split(self, cleaned_text):
            return cleaned_text.split()

    class FrequencyCalculator:
        def calculate(self, words_to_count):
            return collections.Counter(words_to_count)

    def _normalize_input(self, original_text):
        normalizer_instance = self.InputNormalizer()
        lower_case_text = normalizer_instance.normalize(original_text)

        remover_instance = self.PunctuationRemover()
        cleaned_text = remover_instance.clean(lower_case_text)
        return cleaned_text

    def _split_into_words(self, processed_text):
        splitter_instance = self.WordSplitter()
        return splitter_instance.split(processed_text)

    def _count_word_occurrences(self, word_collection):
        calculator_instance = self.FrequencyCalculator()
        return dict(calculator_instance.calculate(word_collection))

