        self.full_name_string = full_name_string

    def get_initials(self):
        class InitialGenerator:
            def __init__(self, name_parts):
                self.name_parts = name_parts

            def process_parts(self):
                class InitialFormatter:
                    def __init__(self, chars):
                        self.chars = chars

                    def format_output(self):
                        return ".".join(self.chars)

                class CharExtractor:
                    def __init__(self, part):
                        self.part = part

                    def get_first_char(self):
                        return self.part[0].upper()

                initial_characters = []
                for part in self.name_parts:
                    if part:
                        extractor = CharExtractor(part)
                        initial_characters.append(extractor.get_first_char())
                formatter = InitialFormatter(initial_characters)
                return formatter.format_output()

        class NameSplitter:
            def __init__(self, name_text):
                self.name_text = name_text

            def split_into_words(self):
                return [word for word in self.name_text.strip().split(' ') if word]

        if not self.full_name_string:
            return ""

        splitter = NameSplitter(self.full_name_string)
        parts = splitter.split_into_words()

        if not parts:
            return ""

        generator = InitialGenerator(parts)
        return generator.process_parts()

