class DigitConverter:
    def convert(self, current_binary_digit, previous_binary_digit_value):
        converted_value = str(int(current_binary_digit.value) ^ int(previous_binary_digit_value))
        return GrayDigit(converted_value)

class StringProcessor:
    def __init__(self):
        self.converter = DigitConverter()

    def process(self, binary_input):
        if not binary_input.binary_string:
            return GrayOutputString('')

        gray_digits = []
        gray_digits.append(GrayDigit(binary_input.binary_string[0]))

        for index in range(1, len(binary_input.binary_string)):
            current_binary_digit = BinaryDigit(binary_input.binary_string[index])
            previous_binary_digit_value = binary_input.binary_string[index - 1]
            gray_digits.append(self.converter.convert(current_binary_digit, previous_binary_digit_value))

        return GrayOutputString("".join(gd.value for gd in gray_digits))

