class date_calculator:
    def __init__(self):
        self.month_day_counts = {
            1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
            7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
        }

class leap_year_checker:
    def is_leap(self, year_value):
        return (year_value % 4 == 0 and year_value % 100 != 0) or (year_value % 400 == 0)

class month_day_provider:
    def get_days(self, month_number, is_leap_year):
        base_days = date_calculator().month_day_counts[month_number]
        if month_number == 2 and is_leap_year:
            return base_days + 1
        return base_days

class input_validator:
    def validate_inputs(self, year_input, month_input):
        if not (1 <= month_input <= 12):
            raise ValueError("Month number must be between 1 and 12.")
        if not (year_input > 0):
            raise ValueError("Year must be a positive integer.")

class result_formatter:
    def format_output(self, day_count):
        return int(day_count)

class year_details:
    def __init__(self, year_value):
        self.year_value = year_value

class month_details:
    def __init__(self, month_value):
        self.month_value = month_value

def count_days_in_month(year_param, month_param):
    input_handler = input_validator()
    input_handler.validate_inputs(year_param, month_param)

    current_year = year_details(year_param)
    current_month = month_details(month_param)

    leap_status_evaluator = leap_year_checker()
    is_current_year_leap = leap_status_evaluator.is_leap(current_year.year_value)

    day_quantity_finder = month_day_provider()
    days_in_target_month = day_quantity_finder.get_days(current_month.month_value, is_current_year_leap)

    output_preparer = result_formatter()
    final_day_count = output_preparer.format_output(days_in_target_month)

    return final_day_count

