import re

class HashtagExtractor:
    def __init__(self):
        self.hashtagPattern = re.compile(r'#([a-zA-Z0-9_]+)')

    def extract_hashtags(self, inputText):
        class TextProcessor:
            def __init__(self, text):
                self.originalText = text

            def get_processed_text(self):
                return self.originalText

        class HashtagCollection:
            def __init__(self):
                self.extractedItems = []

            def add_item(self, item):
                self.extractedItems.append(item)

            def get_all_items(self):
                return self.extractedItems

        class MatchedItemProcessor:
            def process_match(self, matchObject):
                return matchObject.group(1)

        processedInput = TextProcessor(inputText)
        allHashtagMatches = self.hashtagPattern.finditer(processedInput.get_processed_text())

        resultingHashtags = HashtagCollection()
        itemProcessor = MatchedItemProcessor()

        for singleMatch in allHashtagMatches:
            class SingleMatchHandler:
                def __init__(self, match):
                    self.currentMatch = match
                def get_processed_value(self, processor):
                    return processor.process_match(self.currentMatch)

            matchHandler = SingleMatchHandler(singleMatch)
            extractedValue = matchHandler.get_processed_value(itemProcessor)
            resultingHashtags.add_item(extractedValue)

        class FinalResultTransformer:
            def transform(self, collection):
                return collection.get_all_items()

        transformer = FinalResultTransformer()
        return transformer.transform(resultingHashtags)

extractor = HashtagExtractor()
class InputString:
    def __init__(self, text):
        self.inputData = text

firstInput = InputString('This is a #test with #Python.')
secondInput = InputString('No hashtags here!')

class FunctionRunner:
    def execute(self, ext, data):
        return ext.extract_hashtags(data.inputData)

runner = FunctionRunner()
exampleOneResult = runner.execute(extractor, firstInput)
exampleTwoResult = runner.execute(extractor, secondInput)

class ResultPrinter:
    def print_result(self, result):
        print(result)

printer = ResultPrinter()
printer.print_result(exampleOneResult)
printer.print_result(exampleTwoResult)

